pragma solidity ^0.8.0;

import "@openzeppelin/contracts/token/ERC20/extensions/ERC20Pausable.sol";
import "@openzeppelin/contracts/access/Ownable.sol";

contract CustomToken is ERC20Pausable, Ownable {
    mapping(address => bool) public blacklisted;
    uint256 public maxTotalSupply;

    constructor(uint256 initialSupply, uint256 _maxTotalSupply) ERC20("CustomToken", "CTK") {
        _mint(msg.sender, initialSupply);
        maxTotalSupply = _maxTotalSupply;
    }

    function mint(address to, uint256 amount) public onlyOwner whenNotPaused {
        require(totalSupply() + amount <= maxTotalSupply, "Exceeds maximum total supply");
        _mint(to, amount);
    }

    function burn(uint256 amount) public {
        _burn(msg.sender, amount);
    }

    function blacklistAddress(address account) public onlyOwner {
        blacklisted[account] = true;
    }

    function whitelistAddress(address account) public onlyOwner {
        blacklisted[account] = false;
    }

    function pause() public onlyOwner whenNotPaused {
        _pause();
    }

    function unpause() public onlyOwner whenPaused {
        _unpause();
    }

    function transfer(address recipient, uint256 amount) public override returns (bool) {
        require(!blacklisted[msg.sender] && !blacklisted[recipient], "Blacklisted address");
        return super.transfer(recipient, amount);
    }

    function transferFrom(address sender, address recipient, uint256 amount) public override returns (bool) {
        require(!blacklisted[sender] && !blacklisted[recipient], "Blacklisted address");
        return super.transferFrom(sender, recipient, amount);
    }
}

