pragma solidity ^0.8.0;

import "@openzeppelin/contracts/token/ERC20/extensions/ERC20Votes.sol";
import "@openzeppelin/contracts/token/ERC20/extensions/draft-ERC20Permit.sol";
import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/math/SafeMath.sol";

contract CustomERC20 is ERC20, ERC20Votes, ERC20Permit, Ownable {
    using SafeMath for uint256;

    struct VestingSchedule {
        uint256 startTime;
        uint256 cliffDuration;
        uint256 vestingDuration;
        uint256 amount;
        bool isVested;
    }

    mapping(address => VestingSchedule) public vestingSchedules;
    mapping(address => uint256) public lastVestedTimestamp;

    constructor(uint256 initialSupply) ERC20("CustomERC20", "CEC") ERC20Permit("CustomERC20") {
        _mint(msg.sender, initialSupply);
    }

    function mint(address to, uint256 amount) external onlyOwner {
        _mint(to, amount);
    }

    function burn(uint256 amount) external {
        _burn(_msgSender(), amount);
    }

    function setVestingSchedule(address recipient, uint256 startTime, uint256 cliffDuration, uint256 vestingDuration, uint256 amount) external onlyOwner {
        require(vestingSchedules[recipient].isVested == false, "Already vested");
        vestingSchedules[recipient] = VestingSchedule({
            startTime: startTime,
            cliffDuration: cliffDuration,
            vestingDuration: vestingDuration,
            amount: amount,
            isVested: true
        });
    }

    function claimVesting() external {
        VestingSchedule storage schedule = vestingSchedules[msg.sender];
        require(schedule.isVested, "No vesting schedule found");
        require(block.timestamp >= schedule.startTime + schedule.cliffDuration, "Cliff period not yet over");

        uint256 elapsedTime = block.timestamp - schedule.startTime;
        uint256 vestedAmount = schedule.amount.mul(elapsedTime).div(schedule.vestingDuration);

        if (elapsedTime >= schedule.vestingDuration) {
            vestedAmount = schedule.amount;
            schedule.isVested = false;
        }

        require(vestedAmount > 0, "No tokens to vest");
        _transfer(address(this), msg.sender, vestedAmount);
    }

    function getVestingBalance(address account) external view returns (uint256) {
        VestingSchedule storage schedule = vestingSchedules[account];
        if (!schedule.isVested || block.timestamp < schedule.startTime + schedule.cliffDuration) {
            return 0;
        }

        uint256 elapsedTime = block.timestamp - schedule.startTime;
        uint256 vestedAmount = schedule.amount.mul(elapsedTime).div(schedule.vestingDuration);

        if (elapsedTime >= schedule.vestingDuration) {
            vestedAmount = schedule.amount;
        }

        return vestedAmount.sub(balanceOf(account));
    }

    function _transfer(address sender, address recipient, uint256 amount) internal override(ERC20, ERC20Votes) {
        super._transfer(sender, recipient, amount);
    }

    function _mint(address account, uint256 amount) internal override(ERC20, ERC20Votes) {
        super._mint(account, amount);
    }

    function _burn(address account, uint256 amount) internal override(ERC20, ERC20Votes) {
        super._burn(account, amount);
    }
}

