import "@openzeppelin/contracts/utils/cryptography/MerkleProof.sol";

contract WhitelistMintNFT is ERC721, ERC721Enumerable, ERC721URIStorage, ERC721Burnable, Ownable {
    using Strings for uint256;

    bytes32 public merkleRoot;
    bool public whitelistActive = false;
    string private baseTokenURI;
    uint256 public maxSupply = 1000;
    uint256 public mintPrice = 0.01 ether;
    address payable public royaltyRecipient;

    constructor(string memory _name, string memory _symbol, bytes32 _merkleRoot, address _royaltyRecipient)
        ERC721(_name, _symbol)
    {
        merkleRoot = _merkleRoot;
        royaltyRecipient = payable(_royaltyRecipient);
    }

    function setMerkleRoot(bytes32 _newMerkleRoot) public onlyOwner {
        merkleRoot = _newMerkleRoot;
    }

    function toggleWhitelist() public onlyOwner {
        whitelistActive = !whitelistActive;
    }

    function setBaseURI(string memory _baseTokenURI) public onlyOwner {
        baseTokenURI = _baseTokenURI;
    }

    function setMaxSupply(uint256 _newMaxSupply) public onlyOwner {
        maxSupply = _newMaxSupply;
    }

    function setMintPrice(uint256 _newMintPrice) public onlyOwner {
        mintPrice = _newMintPrice;
    }

    function setRoyaltyRecipient(address payable _newRoyaltyRecipient) public onlyOwner {
        royaltyRecipient = _newRoyaltyRecipient;
    }

    function mintWhitelisted(uint256 numberOfTokens, bytes32[] memory proof) public payable {
        require(whitelistActive, "Whitelist is not active");
        require(numberOfTokens <= 10, "Cannot mint more than 10 tokens at a time");
        require(totalSupply() + numberOfTokens <= maxSupply, "Exceeds maximum supply");
        require(msg.value == mintPrice * numberOfTokens, "Incorrect amount sent");
        require(verifyMerkleProof(proof), "Invalid proof");

        for (uint256 i = 0; i < numberOfTokens; i++) {
            _safeMint(msg.sender, totalSupply());
        }
    }

    function verifyMerkleProof(bytes32[] memory proof) private view returns (bool) {
        bytes32 leaf = keccak256(abi.encodePacked(msg.sender));
        return MerkleProof.verify(proof, merkleRoot, leaf);
    }

    function tokenURI(uint256 tokenId)
        public
        view
        override(ERC721, ERC721URIStorage)
        returns (string memory)
    {
        require(_exists(tokenId), "ERC721Metadata: URI query for nonexistent token");
        return bytes(baseTokenURI).length > 0 ? string(abi.encodePacked(baseTokenURI, tokenId.toString())) : "";
    }

    function supportsInterface(bytes4 interfaceId)
        public
        view
        override(ERC721, ERC721Enumerable)
        returns (bool)
    {
        return super.supportsInterface(interfaceId);
    }

    function _burn(uint256 tokenId) internal override(ERC721, ERC721URIStorage) {
        super._burn(tokenId);
    }

    function _baseURI() internal view virtual override returns (string memory) {
        return baseTokenURI;
    }

    function _beforeTokenTransfer(address from, address to, uint256 tokenId)
        internal
        override(ERC721, ERC721Enumerable)
    {
        super._beforeTokenTransfer(from, to, tokenId);
    }
}

