pragma solidity ^0.8.4;

import "@openzeppelin/contracts/token/ERC721/extensions/ERC721URIStorage.sol";
import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/cryptography/MerkleProof.sol";

contract LazyMintNFT is ERC721URIStorage, Ownable {
    bytes32 public merkleRoot;
    mapping(uint256 => bool) private _isTokenMinted;

    event TokenLazyMinted(uint256 indexed tokenId);
    event AllowlistUpdated(bytes32 indexed newRoot);

    constructor(string memory name, string memory symbol)
        ERC721(name, symbol)
    {}

    function setAllowlistRoot(bytes32 root) external onlyOwner {
        merkleRoot = root;
        emit AllowlistUpdated(root);
    }

    function lazyMint(uint256 tokenId, bytes32[] calldata proof) external {
        require(_isTokenMinted[tokenId] == false, "Token already minted");
        require(verifyProof(tokenId, proof), "Invalid proof");

        _safeMint(msg.sender, tokenId);
        _setTokenURI(tokenId, generateMetadata(tokenId));
        _isTokenMinted[tokenId] = true;
        emit TokenLazyMinted(tokenId);
    }

    function batchMint(uint256[] calldata tokenIds, bytes32[][] calldata proofs) external {
        for (uint256 i = 0; i < tokenIds.length; i++) {
            lazyMint(tokenIds[i], proofs[i]);
        }
    }

    function verifyProof(uint256 tokenId, bytes32[] calldata proof) internal view returns (bool) {
        require(_isTokenMinted[tokenId] == false, "Token already minted");
        return MerkleProof.verify(proof, merkleRoot, keccak256(abi.encodePacked(tokenId)));
    }

    function generateMetadata(uint256 tokenId) internal pure returns (string memory) {
        return string(abi.encodePacked("ipfs://", uint2str(tokenId), ".json"));
    }

    function uint2str(uint _i) internal pure returns (string memory) {
        if (_i == 0) return "0";
        uint j = _i;
        uint len;
        while (j != 0) {
            len++;
            j /= 10;
        }
        bytes memory bstr = new bytes(len);
        uint k = len;
        while (_i != 0) {
            k--;
            bstr[k] = byte(uint8(48 + _i % 10));
            _i /= 10;
        }
        return string(bstr);
    }

    function royaltyInfo(uint256 tokenId, uint256 salePrice)
        public
        view
        override
        returns (address receiver, uint256 royaltyAmount)
    {
        require(_exists(tokenId), "ERC721: URI query for nonexistent token");
        return (owner(), salePrice * 10 / 100); // 10% royalty
    }

    function supportsInterface(bytes4 interfaceId)
        public
        view
        override(ERC721URIStorage, ERC721)
        returns (bool)
    {
        return super.supportsInterface(interfaceId);
    }
}

