pragma solidity ^0.8.0;

import "@openzeppelin/contracts/token/ERC721/extensions/ERC721Enumerable.sol";
import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/security/Pausable.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";

contract StakingNFT is ERC721Enumerable, Ownable, Pausable {
    uint256 public constant REWARD_RATE = 10; // 1% per second
    uint256 public constant STAKING_DURATION = 3600 * 24 * 30; // 30 days
    address public rewardToken;

    mapping(uint256 => uint256) public stakingTime;
    mapping(address => uint256) public userStakedBalance;

    event Staked(address indexed owner, uint256 indexed tokenId);
    event Unstaked(address indexed owner, uint256 indexed tokenId);

    constructor(string memory name, string memory symbol, address _rewardToken)
        ERC721(name, symbol)
    {
        rewardToken = _rewardToken;
    }

    modifier onlyStaker(uint256 tokenId) {
        require(_isApprovedOrOwner(msg.sender, tokenId), "Not authorized");
        _;
    }

    function stake(uint256 tokenId) external onlyStaker(tokenId) whenNotPaused {
        transferFrom(msg.sender, address(this), tokenId);
        stakingTime[tokenId] = block.timestamp;
        userStakedBalance[msg.sender] += 1;
        emit Staked(msg.sender, tokenId);
    }

    function unstake(uint256 tokenId) external onlyStaker(tokenId) whenNotPaused {
        uint256 stakeDuration = block.timestamp - stakingTime[tokenId];
        require(stakeDuration >= STAKING_DURATION, "Staking duration not met");

        transferFrom(address(this), msg.sender, tokenId);
        userStakedBalance[msg.sender] -= 1;
        emit Unstaked(msg.sender, tokenId);

        uint256 reward = stakeDuration * REWARD_RATE;
        IERC20(rewardToken).transfer(msg.sender, reward);
    }

    function pause() external onlyOwner {
        _pause();
    }

    function unpause() external onlyOwner {
        _unpause();
    }

    // Additional functions for managing NFTs and rewards can be added here
}

