import "@openzeppelin/contracts/token/ERC721/extensions/ERC721URIStorage.sol";
import "@openzeppelin/contracts/access/Ownable.sol";

contract DutchAuctionNFT is ERC721URIStorage, Ownable {
    uint public totalSupply;
    uint public startTime;
    uint public initialPrice;
    uint public priceReductionInterval;
    uint public priceReductionFactor;

    constructor(uint _totalSupply, uint _initialPrice, uint _priceReductionInterval, uint _priceReductionFactor)
        ERC721("DutchAuctionNFT", "DA")
    {
        totalSupply = _totalSupply;
        initialPrice = _initialPrice;
        priceReductionInterval = _priceReductionInterval;
        priceReductionFactor = _priceReductionFactor;
        startTime = block.timestamp;

        for (uint i = 0; i < totalSupply; i++) {
            _mint(msg.sender, i);
        }
    }

    function getPrice() public view returns (uint) {
        uint elapsedTime = block.timestamp - startTime;
        uint intervalsPassed = elapsedTime / priceReductionInterval;
        return initialPrice * (10**uint(18 - (intervalsPassed * priceReductionFactor)));
    }

    function mint(address to, uint tokenId) external payable {
        require(tokenId < totalSupply, "Token ID out of bounds");
        require(msg.value >= getPrice(), "Insufficient funds");

        _mint(to, tokenId);
    }
}

