import "@openzeppelin/contracts/token/ERC721/extensions/ERC721Enumerable.sol";
import "@openzeppelin/contracts/access/Ownable.sol";

contract MinimalNFT is ERC721Enumerable, Ownable {
    uint256 public constant MAX_SUPPLY = 1000;
    uint256 private _currentTokenId;

    constructor() ERC721("MinimalNFT", "MNFT") {}

    function mint(address to, uint256 quantity) external onlyOwner {
        require(_currentTokenId + quantity <= MAX_SUPPLY, "Max supply reached");

        for (uint256 i = 0; i < quantity; i++) {
            _safeMint(to, ++_currentTokenId);
        }
    }

    function tokenURI(uint256 tokenId) public view override returns (string memory) {
        require(_exists(tokenId), "Invalid token ID");
        return bytes(_baseURI()).length > 0 ? string(abi.encodePacked(_baseURI(), toString(tokenId))) : "";
    }

    function _baseURI() internal pure override returns (string memory) {
        return "https://example.com/nfts/";
    }

    function toString(uint256 value) internal pure returns (string memory) {
        if (value == 0) {
            return "0";
        }
        uint256 temp = value;
        uint256 digits;
        while (temp != 0) {
            digits++;
            temp /= 10;
        }
        bytes memory buffer = new bytes(digits);
        while (value != 0) {
            digits -= 1;
            buffer[digits] = bytes1(uint8(48 + uint256(value % 10)));
            value /= 10;
        }
        return string(buffer);
    }

    // Override isApprovedForAll to reduce gas costs
    function isApprovedForAll(address owner, address operator) public view override returns (bool) {
        return super.isApprovedForAll(owner, operator);
    }

    // Override supportsInterface to optimize gas usage
    function supportsInterface(bytes4 interfaceId) public view override(ERC721Enumerable) returns (bool) {
        return super.supportsInterface(interfaceId);
    }
}

