contract CustomERC1155 is ERC1155Supply, ERC2981 {
    struct TokenInfo {
        uint256 maxSupply;
        bool hasMaxSupplyReached;
    }

    mapping(uint256 => TokenInfo) public tokenInfo;

    event RoyaltySet(uint256 tokenId, address receiver, uint96 feeNumerator);

    constructor(string memory uri_) ERC1155(uri_) {}

    function mintBatch(
        address to,
        uint256[] memory ids,
        uint256[] memory amounts,
        bytes memory data
    ) public onlyOwner {
        require(ids.length == amounts.length, "Invalid input length");
        for (uint256 i = 0; i < ids.length; i++) {
            _mint(to, ids[i], amounts[i], data);
            if (!tokenInfo[ids[i]].hasMaxSupplyReached) {
                uint256 newSupply = tokenInfo[ids[i]].maxSupply + amounts[i];
                require(newSupply <= tokenInfo[ids[i]].maxSupply, "Exceeds max supply");
                tokenInfo[ids[i]].maxSupply = newSupply;
            }
        }
    }

    function setTokenRoyalty(
        uint256 tokenId,
        address receiver,
        uint96 feeNumerator
    ) public onlyOwner {
        _setTokenRoyalty(tokenId, receiver, feeNumerator);
        emit RoyaltySet(tokenId, receiver, feeNumerator);
    }

    function supportsInterface(bytes4 interfaceId)
        public
        view
        override(ERC1155, ERC2981)
        returns (bool)
    {
        return super.supportsInterface(interfaceId);
    }
}

