pragma solidity ^0.8.0;

contract ERC1155 {
    struct Token {
        uint256 supply;
    }

    mapping(uint256 => Token) public tokens;
    mapping(address => mapping(uint256 => uint256)) public balances;

    event TransferSingle(
        address indexed operator,
        address indexed from,
        address indexed to,
        uint256 id,
        uint256 amount
    );

    function mint(address account, uint256 id, uint256 amount) external {
        require(account != address(0), "ERC1155: mint to the zero address");

        if (tokens[id].supply == 0) {
            emit TransferSingle(msg.sender, address(0), account, id, amount);
        }

        tokens[id].supply += amount;
        balances[account][id] += amount;
    }

    function burn(address account, uint256 id, uint256 amount) external {
        require(account != address(0), "ERC1155: burn from the zero address");

        require(balances[account][id] >= amount, "ERC1155: insufficient balance for burn");

        balances[account][id] -= amount;
        tokens[id].supply -= amount;

        emit TransferSingle(msg.sender, account, address(0), id, amount);
    }

    function transfer(address from, address to, uint256 id, uint256 amount) external {
        require(from != address(0), "ERC1155: transfer from the zero address");
        require(to != address(0), "ERC1155: transfer to the zero address");

        require(balances[from][id] >= amount, "ERC1155: insufficient balance for transfer");

        balances[from][id] -= amount;
        balances[to][id] += amount;

        emit TransferSingle(msg.sender, from, to, id, amount);
    }

    function balanceOf(address account, uint256 id) external view returns (uint256) {
        return balances[account][id];
    }
}

