contract ERC1155MultiToken {
    mapping(uint256 => mapping(address => uint256)) private _balances;
    mapping(uint256 => string) private _uris;

    event TransferSingle(address indexed operator, address indexed from, address indexed to, uint256 id, uint256 amount);
    event URI(string value, uint256 indexed id);

    constructor(string memory uri_) {
        _setURI(uri_);
    }

    function balanceOf(address account, uint256 id) public view virtual returns (uint256) {
        return _balances[id][account];
    }

    function setURI(string memory newuri) public virtual {
        _setURI(newuri);
    }

    function uri(uint256 id) public view virtual returns (string memory) {
        return _uris[id];
    }

    function mint(address to, uint256 id, uint256 amount, bytes memory data) public virtual {
        require(to != address(0), "ERC1155: mint to the zero address");

        _beforeTokenTransfer(address(0), to, id, amount);

        _balances[id][to] += amount;
        emit TransferSingle(msg.sender, address(0), to, id, amount);
    }

    function burn(address from, uint256 id, uint256 amount) public virtual {
        require(from == msg.sender || isApprovedForAll(from, msg.sender), "ERC1155: caller is not owner nor approved");

        _beforeTokenTransfer(from, address(0), id, amount);

        uint256 fromBalance = _balances[id][from];
        require(fromBalance >= amount, "ERC1155: burn amount exceeds balance");
        unchecked {
            _balances[id][from] = fromBalance - amount;
        }
        emit TransferSingle(msg.sender, from, address(0), id, amount);
    }

    function safeTransferFrom(address from, address to, uint256 id, uint256 amount, bytes memory data) public virtual {
        require(to != address(0), "ERC1155: transfer to the zero address");

        address operator = msg.sender;
        require(operator == from || isApprovedForAll(from, operator), "ERC1155: caller is not owner nor approved");

        _beforeTokenTransfer(from, to, id, amount);

        uint256 fromBalance = _balances[id][from];
        require(fromBalance >= amount, "ERC1155: transfer amount exceeds balance");
        unchecked {
            _balances[id][from] = fromBalance - amount;
        }
        _balances[id][to] += amount;

        emit TransferSingle(operator, from, to, id, amount);
    }

    function isApprovedForAll(address account, address operator) public view virtual returns (bool);

    function _setURI(string memory newuri) internal virtual {
        _uris[0] = newuri;
        emit URI(newuri, 0);
    }

    function _beforeTokenTransfer(
        address operator,
        address from,
        address to,
        uint256 id,
        uint256 amount
    ) internal virtual {}
}

