pragma solidity ^0.8.0;

import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/access/Ownable.sol";

contract StakingContract is Ownable {
    IERC20 public stakedToken;
    uint256 public totalStaked;
    mapping(address => uint256) public stakedBalances;
    mapping(address => uint256) public lastStakeTimes;

    event Stake(address indexed user, uint256 amount);
    event Withdraw(address indexed user, uint256 amount);
    event ClaimReward(address indexed user, uint256 amount);

    constructor(address _stakedToken) {
        stakedToken = IERC20(_stakedToken);
    }

    function stake(uint256 _amount) public {
        require(_amount > 0, "Stake amount must be greater than zero");
        bool success = stakedToken.transferFrom(msg.sender, address(this), _amount);
        require(success, "Transfer failed");
        totalStaked += _amount;
        stakedBalances[msg.sender] += _amount;
        lastStakeTimes[msg.sender] = block.timestamp;

        emit Stake(msg.sender, _amount);
    }

    function withdraw(uint256 _amount) public {
        require(stakedBalances[msg.sender] >= _amount, "Insufficient stake balance");
        bool success = stakedToken.transfer(msg.sender, _amount);
        require(success, "Transfer failed");
        totalStaked -= _amount;
        stakedBalances[msg.sender] -= _amount;

        emit Withdraw(msg.sender, _amount);
    }

    function claimReward() public {
        uint256 reward = calculateReward(msg.sender);
        require(reward > 0, "No rewards to claim");
        bool success = stakedToken.transfer(msg.sender, reward);
        require(success, "Transfer failed");
        lastStakeTimes[msg.sender] = block.timestamp;

        emit ClaimReward(msg.sender, reward);
    }

    function calculateReward(address _user) public view returns (uint256) {
        uint256 timeSinceLastStake = block.timestamp - lastStakeTimes[_user];
        if (timeSinceLastStake == 0 || stakedBalances[_user] == 0) return 0;
        // Simple reward calculation: 1% of staked amount per day
        return (stakedBalances[_user] * timeSinceLastStake) / 365 days;
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

contract StakingPool {
    struct Stake {
        uint amount;
        uint startTime;
        uint endTime;
    }

    mapping(address => Stake) public stakes;
    address[] public stakers;
    uint public totalStaked;
    uint public penaltyRate = 1; // 1% penalty rate
    uint[] public rewardRates = [10, 20, 30]; // Reward rates for different lock-up durations (1 month, 3 months, 6 months)
    uint[] public lockUpDurations = [30 days, 90 days, 180 days];

    event Staked(address indexed user, uint amount);
    event Withdrawn(address indexed user, uint amount);

    modifier onlyStaker() {
        require(stakes[msg.sender].amount > 0, "Not a staker");
        _;
    }

    function stake(uint amount, uint lockUpDurationIndex) public {
        require(lockUpDurationIndex < lockUpDurations.length, "Invalid lock-up duration index");
        uint lockUpDuration = lockUpDurations[lockUpDurationIndex];
        uint rewardRate = rewardRates[lockUpDurationIndex];

        stakes[msg.sender] = Stake(amount, block.timestamp, block.timestamp + lockUpDuration);
        totalStaked += amount;

        stakers.push(msg.sender);

        emit Staked(msg.sender, amount);
    }

    function withdraw() public onlyStaker {
        Stake storage stake = stakes[msg.sender];
        require(block.timestamp >= stake.endTime, "Cannot withdraw yet");

        uint earnedReward;
        if (block.timestamp > stake.endTime) {
            earnedReward = stake.amount * rewardRate / 100;
        }

        uint amountToWithdraw = stake.amount + earnedReward;

        delete stakes[msg.sender];
        totalStaked -= stake.amount;
        stakers = _removeAddress(stakers, msg.sender);

        payable(msg.sender).transfer(amountToWithdraw);
        emit Withdrawn(msg.sender, amountToWithdraw);
    }

    function earlyWithdraw() public onlyStaker {
        Stake storage stake = stakes[msg.sender];
        require(block.timestamp < stake.endTime, "Cannot withdraw early");

        uint penaltyAmount = stake.amount * penaltyRate / 100;
        uint amountToWithdraw = stake.amount - penaltyAmount;

        delete stakes[msg.sender];
        totalStaked -= stake.amount;
        stakers = _removeAddress(stakers, msg.sender);

        payable(msg.sender).transfer(amountToWithdraw);
        emit Withdrawn(msg.sender, amountToWithdraw);
    }

    function _removeAddress(address[] storage arr, address addr) internal returns (address[] storage) {
        uint index = 0;
        for (; index < arr.length; index++) {
            if (arr[index] == addr) break;
        }
        for (; index + 1 < arr.length; index++) {
            arr[index] = arr[index + 1];
        }
        if (index == arr.length - 1) {
            arr.pop();
        } else {
            arr[index] = address(0);
        }
        return arr;
    }

    function getStakeInfo(address user) public view returns (uint amount, uint startTime, uint endTime) {
        Stake storage stake = stakes[user];
        return (stake.amount, stake.startTime, stake.endTime);
    }
}

