import "@openzeppelin/contracts/security/ReentrancyGuard.sol";

contract CollateralizedLending is ReentrancyGuard {
    IERC20 public stablecoin;
    uint256 public loanInterestRate;

    struct Loan {
        address borrower;
        uint256 amountBorrowed;
        uint256 collateralDeposited;
        uint256 repaymentDeadline;
    }

    mapping(address => Loan) public loans;
    address[] public lenders;

    event LoanCreated(address indexed borrower, uint256 amountBorrowed, uint256 collateralDeposited);
    event LoanRepaid(address indexed borrower, uint256 amountRepaid);

    constructor(address _stablecoinAddress, uint256 _loanInterestRate) {
        stablecoin = IERC20(_stablecoinAddress);
        loanInterestRate = _loanInterestRate;
    }

    function borrow(uint256 _amountBorrowed, uint256 _collateralDeposited, uint256 _repaymentDeadline) public payable nonReentrant returns (bool) {
        require(msg.value == _collateralDeposited, "Insufficient ETH deposited");
        bool success = stablecoin.transferFrom(msg.sender, address(this), _amountBorrowed);
        require(success, "Transfer failed");
        loans[msg.sender] = Loan({
            borrower: msg.sender,
            amountBorrowed: _amountBorrowed,
            collateralDeposited: _collateralDeposited,
            repaymentDeadline: block.timestamp + _repaymentDeadline
        });
        emit LoanCreated(msg.sender, _amountBorrowed, _collateralDeposited);
        return true;
    }

    function repay() public nonReentrant returns (bool) {
        require(loans[msg.sender].borrower == msg.sender, "Not a borrower");
        uint256 amountRepaid = loans[msg.sender].amountBorrowed + (loans[msg.sender].amountBorrowed * loanInterestRate / 100);
        bool success = stablecoin.transfer(msg.sender, amountRepaid);
        require(success, "Transfer failed");
        delete loans[msg.sender];
        emit LoanRepaid(msg.sender, amountRepaid);
        return true;
    }

    function getLoanDetails(address _borrower) public view returns (uint256, uint256, uint256, uint256) {
        Loan memory loan = loans[_borrower];
        return (loan.amountBorrowed, loan.collateralDeposited, loan.repaymentDeadline, block.timestamp);
    }

    function getLenders() public view returns (address[] memory) {
        return lenders;
    }
}

