pragma solidity ^0.8.0;

contract LendingProtocol {
    struct User {
        uint256 collateral;
        uint256 debt;
    }

    struct TokenInfo {
        uint256 interestRate;
        uint256 liquidationThreshold;
    }

    mapping(address => User) public users;
    mapping(address => TokenInfo) public tokenInfos;

    event Borrowed(address indexed user, address indexed asset, uint256 amount);
    event Repaid(address indexed user, address indexed asset, uint256 amount);
    event Liquidated(address indexed user);

    function borrow(address asset, uint256 amount) external {
        require(users[msg.sender].collateral >= amount, "Insufficient collateral");
        users[msg.sender].debt += amount;
        emit Borrowed(msg.sender, asset, amount);
    }

    function repay(address asset, uint256 amount) external {
        require(users[msg.sender].debt >= amount, "Debt too low");
        users[msg.sender].debt -= amount;
        emit Repaid(msg.sender, asset, amount);
    }

    function liquidate(address user) external {
        require(calculateHealthFactor(user) < 1, "User is not undercollateralized");
        // Perform liquidation logic here
        emit Liquidated(user);
    }

    function calculateHealthFactor(address user) public view returns (uint256) {
        User storage u = users[user];
        uint256 interest = u.debt * tokenInfos[u.collateral].interestRate / 100;
        return (u.collateral + interest) / u.debt;
    }
}

