pragma solidity ^0.8.0;

import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import "@openzeppelin/contracts/security/ReentrancyGuard.sol";
import "@openzeppelin/contracts/access/Ownable.sol";

contract LendingProtocol is Ownable, ReentrancyGuard {
    using SafeERC20 for IERC20;

    struct CollateralType {
        uint8 id;
        string name;
        address tokenAddress;
        uint256 minCollateralRatio; // Minimum collateral ratio required
    }

    struct Loan {
        address borrower;
        address lender;
        uint256 amount;
        uint256 interestRate;
        uint256 repayDeadline;
        bool isRepaid;
    }

    mapping(uint8 => CollateralType) public collateralTypes;
    mapping(address => uint256) public userBalance;
    mapping(address => uint256) public loanAmount;
    mapping(address => uint256) public loanInterestRate;
    mapping(address => uint256) public loanRepayDeadline;
    address[] public activeLoans;

    event LoanCreated(address borrower, address lender, uint256 amount, uint256 interestRate);
    event LoanRepaid(address borrower, uint256 amount);
    event LiquidationInitiated(address borrower);

    function addCollateralType(uint8 id, string memory name, address tokenAddress, uint256 minCollateralRatio) public onlyOwner {
        collateralTypes[id] = CollateralType(id, name, tokenAddress, minCollateralRatio);
    }

    function borrow(uint256 amount, uint8 collateralTypeId) public nonReentrant {
        require(collateralTypes[collateralTypeId].id != 0, "Invalid collateral type");
        require(amount > 0, "Amount must be greater than zero");

        CollateralType storage collateral = collateralTypes[collateralTypeId];
        IERC20 collateralToken = IERC20(collateral.tokenAddress);
        collateralToken.safeTransferFrom(msg.sender, address(this), amount);

        uint256 interestRate = calculateInterestRate(amount);
        uint256 repayDeadline = block.timestamp + 7 days; // Example: 1 week

        loanAmount[msg.sender] += amount;
        loanInterestRate[msg.sender] = interestRate;
        loanRepayDeadline[msg.sender] = repayDeadline;

        activeLoans.push(msg.sender);

        emit LoanCreated(msg.sender, msg.sender, amount, interestRate);
    }

    function repay() public nonReentrant {
        require(loanAmount[msg.sender] > 0, "No outstanding loans");

        uint256 totalAmountRepay = loanAmount[msg.sender] + calculateInterest(loanAmount[msg.sender], loanInterestRate[msg.sender]);

        IERC20 stablecoinToken = IERC20(collateralTypes[1].tokenAddress); // Assuming collateral type 1 is the stablecoin
        stablecoinToken.safeTransferFrom(msg.sender, address(this), totalAmountRepay);

        userBalance[msg.sender] += totalAmountRepay;
        loanAmount[msg.sender] = 0;

        emit LoanRepaid(msg.sender, totalAmountRepay);
    }

    function liquidate(address borrower) public nonReentrant {
        require(loanRepayDeadline[borrower] < block.timestamp, "Loan not yet overdue");
        require(userBalance[borrower] == 0, "Borrower still has balance");

        uint256 loanAmountToRecover = loanAmount[borrower];
        IERC20 collateralToken = IERC20(collateralTypes[1].tokenAddress);
        collateralToken.safeTransfer(borrower, loanAmountToRecover);

        userBalance[borrower] -= loanAmountToRecover;
        loanAmount[borrower] = 0;

        emit LiquidationInitiated(borrower);
    }

    function calculateInterestRate(uint256 amount) internal view returns (uint256) {
        // Example: Simple utilization-based model
        uint256 totalSupply = userBalance[msg.sender];
        uint256 utilizationRatio = totalSupply > 0 ? amount * 100 / totalSupply : 0;
        return utilizationRatio * 10; // Assuming interest rate of 10% per year for simplicity
    }

    function calculateInterest(uint256 amount, uint256 interestRate) internal pure returns (uint256) {
        return amount * interestRate / 365 days;
    }
}

