pragma solidity ^0.8.0;

contract PeerToPeerLending {
    struct Loan {
        uint256 amount;
        uint256 interestRate;
        uint256 dueDate;
        address lender;
        address borrower;
        bool isCollateralDeposited;
        bool isRepaid;
    }

    mapping(uint256 => Loan) public loans;
    uint256 public loanCount;

    event LoanCreated(uint256 indexed loanId, address indexed lender, address indexed borrower);
    event CollateralDeposited(uint256 indexed loanId, address indexed depositor);
    event LoanRepaid(uint256 indexed loanId);

    function createLoan(
        uint256 _amount,
        uint256 _interestRate,
        uint256 _dueDate
    ) external {
        require(_amount > 0, "Amount must be greater than zero");
        require(_interestRate > 0, "Interest rate must be greater than zero");
        require(_dueDate > block.timestamp, "Due date must be in the future");

        loanCount++;
        loans[loanCount] = Loan({
            amount: _amount,
            interestRate: _interestRate,
            dueDate: _dueDate,
            lender: msg.sender,
            borrower: address(0),
            isCollateralDeposited: false,
            isRepaid: false
        });

        emit LoanCreated(loanCount, msg.sender, address(0));
    }

    function depositCollateral(uint256 _loanId) external payable {
        require(loans[_loanId].lender != address(0), "Loan does not exist");
        require(msg.value > 0, "Amount must be greater than zero");

        loans[_loanId].isCollateralDeposited = true;
        emit CollateralDeposited(_loanId, msg.sender);
    }

    function borrow(uint256 _loanId) external {
        require(loans[_loanId].lender != address(0), "Loan does not exist");
        require(!loans[_loanId].isCollateralDeposited, "Collateral must be deposited first");
        require(block.timestamp < loans[_loanId].dueDate, "Loan has expired");

        loans[_loanId].borrower = msg.sender;
        emit LoanCreated(_loanId, loans[_loanId].lender, msg.sender);
    }

    function repay(uint256 _loanId) external payable {
        require(loans[_loanId].lender != address(0), "Loan does not exist");
        require(msg.value >= (loans[_loanId].amount * (1 + loans[_loanId].interestRate / 100)), "Insufficient repayment amount");
        require(!loans[_loanId].isRepaid, "Loan has already been repaid");

        uint256 interest = msg.value - loans[_loanId].amount;
        payable(loans[_loanId].lender).transfer(msg.value);
        if (interest > 0) {
            payable(msg.sender).transfer(interest);
        }
        loans[_loanId].isRepaid = true;
        emit LoanRepaid(_loanId);
    }

    function getLoanDetails(uint256 _loanId) external view returns (
        uint256 amount,
        uint256 interestRate,
        uint256 dueDate,
        address lender,
        address borrower,
        bool isCollateralDeposited,
        bool isRepaid
    ) {
        require(loans[_loanId].lender != address(0), "Loan does not exist");

        amount = loans[_loanId].amount;
        interestRate = loans[_loanId].interestRate;
        dueDate = loans[_loanId].dueDate;
        lender = loans[_loanId].lender;
        borrower = loans[_loanId].borrower;
        isCollateralDeposited = loans[_loanId].isCollateralDeposited;
        isRepaid = loans[_loanId].isRepaid;
    }
}

