contract DeFiLending {
    struct Loan {
        address borrower;
        uint256 amount;
        uint256 interestRate;
        uint256 dueDate;
        bool isRepaid;
    }

    mapping(uint256 => Loan) public loans;
    uint256 public loanCount;

    event LoanCreated(uint256 indexed loanId, address borrower, uint256 amount, uint256 interestRate, uint256 dueDate);
    event LoanRepaid(uint256 indexed loanId);

    function createLoan(uint256 _amount, uint256 _interestRate, uint256 _dueDate) public {
        require(_amount > 0, "Amount must be greater than zero");
        require(_interestRate > 0, "Interest rate must be greater than zero");
        require(_dueDate > block.timestamp, "Due date must be in the future");

        loanCount++;
        loans[loanCount] = Loan(msg.sender, _amount, _interestRate, _dueDate, false);

        emit LoanCreated(loanCount, msg.sender, _amount, _interestRate, _dueDate);
    }

    function repayLoan(uint256 _loanId) public payable {
        require(loans[_loanId].borrower == msg.sender, "Not the borrower of this loan");
        require(!loans[_loanId].isRepaid, "Loan already repaid");
        require(block.timestamp >= loans[_loanId].dueDate, "Loan is not yet due");

        uint256 amountDue = loans[_loanId].amount + (loans[_loanId].amount * loans[_loanId].interestRate / 100);
        require(msg.value >= amountDue, "Insufficient funds to repay loan");

        loans[_loanId].isRepaid = true;

        emit LoanRepaid(_loanId);

        // Transfer the interest and principal back to the borrower
        payable(loans[_loanId].borrower).transfer(amountDue);
    }

    function getLoanDetails(uint256 _loanId) public view returns (address, uint256, uint256, uint256, bool) {
        require(_loanId > 0 && _loanId <= loanCount, "Invalid loan ID");

        Loan memory loan = loans[_loanId];
        return (loan.borrower, loan.amount, loan.interestRate, loan.dueDate, loan.isRepaid);
    }
}

