pragma solidity ^0.8.0;

contract ConstantProductAMM {
    uint public reserveX;
    uint public reserveY;

    constructor(uint _reserveX, uint _reserveY) {
        require(_reserveX > 0 && _reserveY > 0, "Initial reserves must be greater than zero");
        reserveX = _reserveX;
        reserveY = _reserveY;
    }

    function swapExactIn(uint amountIn, uint minAmountOut) external returns (uint amountOut) {
        require(amountIn > 0, "Input amount must be greater than zero");
        uint initialReserveY = reserveY;
        reserveX += amountIn;
        reserveY -= (amountIn * reserveY / reserveX);
        amountOut = initialReserveY - reserveY;
        require(amountOut >= minAmountOut, "Insufficient output amount");
    }

    function addLiquidity(uint amountX, uint amountY) external returns (uint liquidity) {
        require(amountX > 0 && amountY > 0, "Input amounts must be greater than zero");
        uint totalReserveX = reserveX + amountX;
        uint totalReserveY = reserveY + amountY;
        uint initialLiquidity = liquidityOf(reserveX, reserveY);
        liquidity = liquidityOf(totalReserveX, totalReserveY);
        require(liquidity > 0, "Insufficient liquidity minted");
    }

    function removeLiquidity(uint liquidity) external returns (uint amountX, uint amountY) {
        require(liquidity > 0, "Input liquidity must be greater than zero");
        uint totalLiquidity = liquidityOf(reserveX, reserveY);
        require(totalLiquidity >= liquidity, "Insufficient liquidity available");
        amountX = (reserveX * liquidity / totalLiquidity);
        amountY = (reserveY * liquidity / totalLiquidity);
        reserveX -= amountX;
        reserveY -= amountY;
    }

    function liquidityOf(uint x, uint y) public pure returns (uint liquidity) {
        return sqrt(x * y);
    }

    function sqrt(uint x) internal pure returns (uint y) {
        uint z = (x >> 1) + 1;
        y = x;
        while (z < y) {
            y = z;
            z = (x / z + z) >> 1;
        }
    }
}

