contract DEX {
    IERC20 public tokenA;
    IERC20 public tokenB;

    mapping(address => uint256) public liquidityProviderBalances;
    uint256 public totalLiquidity;

    event LiquidityAdded(address provider, uint256 amountA, uint256 amountB);
    event LiquidityRemoved(address provider, uint256 amountA, uint256 amountB);
    event Swap(address buyer, uint256 amountIn, uint256 amountOut);

    constructor(IERC20 _tokenA, IERC20 _tokenB) {
        tokenA = _tokenA;
        tokenB = _tokenB;
    }

    function addLiquidity(uint256 amountA, uint256 amountB) external {
        require(amountA > 0 && amountB > 0, "Amounts must be greater than zero");
        uint256 liquidity = (amountA * totalLiquidity) / tokenA.balanceOf(msg.sender);
        if (totalLiquidity == 0) {
            liquidityProviderBalances[msg.sender] = liquidity;
        } else {
            require((amountB * tokenA.balanceOf(msg.sender)) / amountA == liquidity, "Imbalanced liquidity");
            liquidityProviderBalances[msg.sender] += liquidity;
        }
        tokenA.transferFrom(msg.sender, address(this), amountA);
        tokenB.transferFrom(msg.sender, address(this), amountB);
        totalLiquidity += liquidity;
        emit LiquidityAdded(msg.sender, amountA, amountB);
    }

    function removeLiquidity(uint256 liquidity) external {
        require(liquidityProviderBalances[msg.sender] >= liquidity, "Insufficient liquidity");
        uint256 amountA = (liquidity * tokenA.balanceOf(address(this))) / totalLiquidity;
        uint256 amountB = (liquidity * tokenB.balanceOf(address(this))) / totalLiquidity;
        liquidityProviderBalances[msg.sender] -= liquidity;
        totalLiquidity -= liquidity;
        tokenA.transfer(msg.sender, amountA);
        tokenB.transfer(msg.sender, amountB);
        emit LiquidityRemoved(msg.sender, amountA, amountB);
    }

    function swap(uint256 amountIn, address tokenFrom) external returns (uint256 amountOut) {
        require(amountIn > 0, "Amount must be greater than zero");
        uint256 reserveA = tokenA.balanceOf(address(this));
        uint256 reserveB = tokenB.balanceOf(address(this));
        if (tokenFrom == address(tokenA)) {
            require(reserveB > 0, "Token B reserve is empty");
            amountOut = (amountIn * reserveB) / reserveA;
            require(amountOut > 0, "Output amount must be greater than zero");
            tokenA.transferFrom(msg.sender, address(this), amountIn);
            tokenB.transfer(msg.sender, amountOut);
        } else {
            require(reserveA > 0, "Token A reserve is empty");
            amountOut = (amountIn * reserveA) / reserveB;
            require(amountOut > 0, "Output amount must be greater than zero");
            tokenB.transferFrom(msg.sender, address(this), amountIn);
            tokenA.transfer(msg.sender, amountOut);
        }
        emit Swap(msg.sender, amountIn, amountOut);
    }
}

