    }

    function addLiquidity(address tokenA, address tokenB, uint amountADesired, uint amountBDesired, uint amountAMin, uint amountBMin, address to, uint deadline) external override returns (uint amountA, uint amountB, uint liquidity) {
        require(amountA > 0 && amountB > 0, 'UniswapV2Router: INSUFFICIENT_AMNTS');
        require(amountADesired >= amountAMin, 'UniswapV2Router: EXCESSIVE_INPUT_AMOUNT');
        require(amountBDesired >= amountBMin, 'UniswapV2Router: EXCESSIVE_INPUT_AMOUNT');

        (amountA, amountB) = UniswapV2Pair(Factory(factory).createPair(tokenA, tokenB)).addLiquidity(
            tokenA,
            tokenB,
            amountADesired,
            amountBDesired,
            amountAMin,
            amountBMin,
            to,
            deadline
        );
    }

    function removeLiquidity(address tokenA, address tokenB, uint liquidity, uint amountAMin, uint amountBMin, address to, uint deadline) external override returns (uint amountA, uint amountB) {
        require(liquidity > 0, 'UniswapV2Router: INSUFFICIENT_LIQUIDITY');

        UniswapV2Pair pair = UniswapV2Pair(Factory(factory).getPair(tokenA, tokenB));
        address token0 = pair.token0();
        address token1 = pair.token1();

        (amountA, amountB) = pair.removeLiquidity(
            token0,
            token1,
            liquidity,
            amountAMin,
            amountBMin,
            to,
            deadline
        );
    }

    function swapExactTokensForTokens(uint amountIn, uint amountOutMin, address[] calldata path, address to, uint deadline) external override returns (uint[] memory amounts) {
        require(path.length >= 2, 'UniswapV2Router: INVALID_PATH');
        for (uint i; i < path.length - 1; i++) {
            (amountIn, ) = _swap(amountIn, amountOutMin, path[i], path[i + 1]);
        }
        return amounts;
    }

    function _swap(uint amountIn, uint amountOutMin, address tokenIn, address tokenOut) private returns (uint amountOut, uint amountInLeftover) {
        UniswapV2Pair pair = UniswapV2Pair(Factory(factory).getPair(tokenIn, tokenOut));
        (uint reserve0, uint reserve1, ) = pair.getReserves();
        require(reserve0 > 0 && reserve1 > 0, 'UniswapV2Router: INSUFFICIENT_LIQUIDITY');

