import "@openzeppelin/contracts/token/ERC20/IERC20.sol";

contract OrderBook {
    struct LimitOrder {
        address trader;
        uint256 amountTokenA;
        uint256 amountTokenB;
        uint256 price;
        bool isBuyOrder;
    }

    mapping(address => LimitOrder[]) public orders;

    event OrderPlaced(address indexed trader, bool isBuyOrder, uint256 amountTokenA, uint256 amountTokenB, uint256 price);

    function placeOrder(bool isBuyOrder, uint256 amountTokenA, uint256 amountTokenB, uint256 price) public {
        require(amountTokenA > 0 && amountTokenB > 0, "Amounts must be greater than zero");
        orders[msg.sender].push(LimitOrder(msg.sender, amountTokenA, amountTokenB, price, isBuyOrder));
        emit OrderPlaced(msg.sender, isBuyOrder, amountTokenA, amountTokenB, price);
    }

    function fillOrder(address trader, uint256 orderId) public {
        require(orders[trader][orderId].isBuyOrder != orders[msg.sender][0].isBuyOrder, "Cross-order matching");
        LimitOrder memory order = orders[trader][orderId];
        uint256 price = order.price;
        uint256 amountTokenA = orders[msg.sender][0].amountTokenA;
        uint256 amountTokenB = orders[msg.sender][0].amountTokenB;

        if (orders[msg.sender][0].isBuyOrder) {
            require(amountTokenB >= price * amountTokenA / 1e18, "Insufficient funds for trade");
            IERC20(order.amountTokenB).transferFrom(msg.sender, trader, amountTokenB);
            IERC20(order.amountTokenA).transfer(msg.sender, order.amountTokenA);
        } else {
            require(amountTokenA >= price * amountTokenB / 1e18, "Insufficient funds for trade");
            IERC20(order.amountTokenA).transferFrom(msg.sender, trader, amountTokenA);
            IERC20(order.amountTokenB).transfer(msg.sender, order.amountTokenB);
        }

        delete orders[trader][orderId];
        delete orders[msg.sender][0];
    }
}

