contract CustomAMM {
    uint256 public reserveTokenA;
    uint256 public reserveTokenB;
    bool public isLinearCurve;

    constructor(uint256 _reserveTokenA, uint256 _reserveTokenB) {
        reserveTokenA = _reserveTokenA;
        reserveTokenB = _reserveTokenB;
        isLinearCurve = true; // Default to linear curve
    }

    function setBondingCurve(bool _isLinearCurve) external {
        isLinearCurve = _isLinearCurve;
    }

    function calculatePrice(uint256 inputAmount, uint256 reserveInput, uint256 reserveOutput) internal pure returns (uint256) {
        if (isLinearCurve) {
            return (reserveOutput * inputAmount) / (reserveInput + inputAmount);
        } else {
            uint256 k = reserveInput * reserveOutput;
            uint256 newInput = reserveInput + inputAmount;
            uint256 newOutput = k / newInput;
            return reserveOutput - newOutput;
        }
    }

    function swap(uint256 amountIn, address to) external returns (uint256 amountOut) {
        if (to == address(0)) revert("Invalid recipient");
        uint256 inputReserve = isLinearCurve ? reserveTokenA : reserveTokenB;
        uint256 outputReserve = isLinearCurve ? reserveTokenB : reserveTokenA;
        amountOut = calculatePrice(amountIn, inputReserve, outputReserve);
        if (amountOut == 0) revert("Insufficient liquidity");
        if (isLinearCurve) {
            reserveTokenA += amountIn;
            reserveTokenB -= amountOut;
        } else {
            reserveTokenA -= amountIn;
            reserveTokenB += amountOut;
        }
    }

    function addLiquidity(uint256 amountA, uint256 amountB) external {
        if (amountA == 0 || amountB == 0) revert("Zero liquidity added");
        reserveTokenA += amountA;
        reserveTokenB += amountB;
    }

    function removeLiquidity(uint256 amountA, uint256 amountB) external {
        if (amountA > reserveTokenA || amountB > reserveTokenB) revert("Insufficient liquidity");
        reserveTokenA -= amountA;
        reserveTokenB -= amountB;
    }
}

