pragma solidity ^0.8.0;

contract AMM {
    using SafeMath for uint256;

    address public tokenA;
    address public tokenB;
    uint256 public reserveA;
    uint256 public reserveB;

    event Swap(address indexed sender, uint256 amountInA, uint256 amountOutA, uint256 amountInB, uint256 amountOutB);

    constructor(address _tokenA, address _tokenB) {
        require(_tokenA != address(0), "Token A cannot be the zero address");
        require(_tokenB != address(0), "Token B cannot be the zero address");

        tokenA = _tokenA;
        tokenB = _tokenB;
    }

    function addLiquidity(uint256 amountA, uint256 amountB) public returns (uint256 liquidity) {
        require(amountA > 0 && amountB > 0, "Amounts must be greater than zero");

        reserveA += amountA;
        reserveB += amountB;

        liquidity = getLiquidityForTokens(amountA, amountB);
    }

    function removeLiquidity(uint256 liquidity) public returns (uint256 amountA, uint256 amountB) {
        require(liquidity > 0, "Invalid liquidity");

        uint totalLiquidity = reserveA + reserveB;

        amountA = liquidity.mul(reserveA).div(totalLiquidity);
        amountB = liquidity.mul(reserveB).div(totalLiquidity);

        reserveA -= amountA;
        reserveB -= amountB;
    }

    function swap(uint256 amountInA, uint256 minAmountOutA, uint256 minAmountOutB) public returns (uint256 amountOutA, uint256 amountOutB) {
        require(amountInA > 0, "Amount must be greater than zero");

        reserveA += amountInA;
        uint256 amountToBurn = calculateBurnAmount(reserveA, reserveB);

        reserveB -= amountToBurn;

        amountOutA = calculateOutputAmount(reserveA - amountInA, reserveB + amountToBurn, minAmountOutA);
        amountOutB = calculateOutputAmount(reserveB - amountToBurn, reserveA + amountInA, minAmountOutB);

        emit Swap(msg.sender, amountInA, amountOutA, 0, amountOutB);
    }

    function getLiquidityForTokens(uint256 amountA, uint256 amountB) public view returns (uint256 liquidity) {
        if(reserveA == 0 || reserveB == 0) return 0;

        uint totalReserves = reserveA + reserveB;
        uint reserveRatioA = reserveA.mul(1e18).div(totalReserves);
        uint reserveRatioB = reserveB.mul(1e18).div(totalReserves);

        if(amountA * reserveRatioB > amountB * reserveRatioA) {
            return (amountB * 1e18).div(reserveRatioB);
        } else {
            return (amountA * 1e18).div(reserveRatioA);
        }
    }

    function calculateBurnAmount(uint256 _reserveA, uint256 _reserveB) public view returns (uint256 burnAmount) {
        return (_reserveA.mul(_reserveB)).sqrt();
    }

    function calculateOutputAmount(uint256 reserveIn, uint256 reserveOut, uint256 minAmountOut) public pure returns (uint256 amountOut) {
        require(minAmountOut > 0, "Min output must be greater than zero");

        uint amountInWithFee = reserveIn.mul(1000);
        uint numerator = amountInWithFee * reserveOut;
        uint denominator = reserveIn + amountInWithFee;

        amountOut = numerator / denominator;

        require(amountOut >= minAmountOut, "Insufficient output");
    }
}

library SafeMath {
    function add(uint256 a, uint256 b) internal pure returns (uint256) {
        return a + b;
    }

    function sub(uint256 a, uint256 b) internal pure returns (uint256) {
        require(a >= b);
        return a - b;
    }

    function mul(uint256 a, uint256 b) internal pure returns (uint256) {
        if (a == 0) return 0;
        uint c = a * b;
        require(c / a == b);
        return c;
    }

    function div(uint256 a, uint256 b) internal pure returns (uint256) {
        require(b > 0);
        uint c = a / b;
        return c;
    }

    function sqrt(uint256 y) internal pure returns (uint256 z) {
        if (y > 3) {
            z = y;
            uint x = y / 2 + 1;
            while (x < z) {
                z = x;
                x = (y / x + x) / 2;
            }
        } else if (y != 0) {
            z = 1;
        }
    }
}

