import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import "@openzeppelin/contracts/access/Ownable.sol";

contract YieldVault is Ownable {
    using SafeERC20 for IERC20;

    IERC20 public underlyingToken;
    IERC20 public vaultToken;
    address public strategy;

    event Deposit(address indexed user, uint256 amount);
    event Withdrawal(address indexed user, uint256 shares);

    constructor(IERC20 _underlyingToken, IERC20 _vaultToken, address _strategy) {
        underlyingToken = _underlyingToken;
        vaultToken = _vaultToken;
        strategy = _strategy;
    }

    function deposit(uint256 amount) external {
        underlyingToken.safeTransferFrom(msg.sender, address(this), amount);
        uint256 shares = convertToShares(amount);
        vaultToken.mint(msg.sender, shares);
        IERC20(strategy).safeTransfer(address(this), amount);
        emit Deposit(msg.sender, amount);
    }

    function withdraw(uint256 shares) external {
        require(vaultToken.balanceOf(msg.sender) >= shares, "Insufficient shares");
        uint256 amount = convertToAssets(shares);
        vaultToken.burnFrom(msg.sender, shares);
        underlyingToken.safeTransfer(msg.sender, amount);
        IERC20(strategy).safeTransfer(msg.sender, amount);
        emit Withdrawal(msg.sender, shares);
    }

    function convertToShares(uint256 amount) public view returns (uint256) {
        uint256 totalAssets = getTotalAssets();
        return totalAssets == 0 ? amount : (amount * vaultToken.totalSupply()) / totalAssets;
    }

    function convertToAssets(uint256 shares) public view returns (uint256) {
        uint256 totalShares = vaultToken.totalSupply();
        return totalShares == 0 ? shares : (shares * getTotalAssets()) / totalShares;
    }

    function getTotalAssets() public view returns (uint256) {
        // Assuming the strategy's balance is the total assets
        return IERC20(strategy).balanceOf(address(this));
    }

    function setStrategy(address _strategy) external onlyOwner {
        strategy = _strategy;
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

interface IStrategy {
    function deposit(uint256 _amount) external;
    function withdraw(uint256 _amount) external;
    function harvest() external;
}

contract YieldAggregatorVault {
    address public owner;
    uint256 public totalDeposits;
    uint256 public feeRate; // Fee rate in basis points (1% = 100)
    IStrategy public strategy;

    constructor(uint256 _feeRate, address _strategy) {
        require(_feeRate <= 10000, "Invalid fee rate");
        owner = msg.sender;
        feeRate = _feeRate;
        strategy = IStrategy(_strategy);
    }

    modifier onlyOwner() {
        require(msg.sender == owner, "Not the owner");
        _;
    }

    function deposit(uint256 _amount) external payable onlyOwner {
        uint256 fees = (_amount * feeRate) / 10000;
        totalDeposits += _amount - fees;
        strategy.deposit(_amount - fees);
    }

    function withdraw(uint256 _amount) external onlyOwner returns (uint256) {
        require(totalDeposits >= _amount, "Insufficient balance");
        uint256 fees = (_amount * feeRate) / 10000;
        totalDeposits -= _amount;
        strategy.withdraw(_amount - fees);
        return _amount - fees;
    }

    function harvest() external onlyOwner {
        strategy.harvest();
    }

    function setStrategy(address _strategy) external onlyOwner {
        strategy = IStrategy(_strategy);
    }

    function setFeeRate(uint256 _feeRate) external onlyOwner {
        require(_feeRate <= 10000, "Invalid fee rate");
        feeRate = _feeRate;
    }
}

