pragma solidity ^0.8.0;

import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import "@openzeppelin/contracts/access/Ownable.sol";

interface IStrategy {
    function deposit(uint256 _amount) external;
    function withdraw(uint256 _amount) external;
    function harvest() external;
    function balanceOf() external view returns (uint256);
}

contract MultiStrategyYieldVault is Ownable {
    using SafeERC20 for IERC20;

    struct StrategyInfo {
        address strategy;
        uint256 weight;
        uint256 lastHarvestTime;
    }

    mapping(address => StrategyInfo) public strategies;
    IERC20 public vaultToken;
    uint256 public totalWeight;
    uint256 public performanceFee;

    event StrategyAdded(address indexed strategy, uint256 weight);
    event StrategyRemoved(address indexed strategy);
    event Harvested(address indexed strategy, uint256 amount);
    event PerformanceFeeWithdrawn(uint256 amount);

    constructor(IERC20 _vaultToken, uint256 _performanceFee) {
        vaultToken = _vaultToken;
        performanceFee = _performanceFee;
    }

    function addStrategy(address _strategy, uint256 _weight) external onlyOwner {
        require(strategies[_strategy].strategy == address(0), "Strategy already added");
        strategies[_strategy] = StrategyInfo(_strategy, _weight, 0);
        totalWeight += _weight;
        emit StrategyAdded(_strategy, _weight);
    }

    function removeStrategy(address _strategy) external onlyOwner {
        require(strategies[_strategy].strategy != address(0), "Strategy not added");
        uint256 weight = strategies[_strategy].weight;
        totalWeight -= weight;
        delete strategies[_strategy];
        emit StrategyRemoved(_strategy);
    }

    function deposit(uint256 _amount) external {
        vaultToken.safeTransferFrom(msg.sender, address(this), _amount);
        for (uint256 i = 0; i < totalWeight; i++) {
            uint256 weight = strategies[i].weight;
            if (weight > 0) {
                uint256 amountToDeposit = (_amount * weight) / totalWeight;
                IStrategy(strategies[i].strategy).deposit(amountToDeposit);
            }
        }
    }

    function withdraw(uint256 _amount) external onlyOwner {
        for (uint256 i = 0; i < totalWeight; i++) {
            uint256 weight = strategies[i].weight;
            if (weight > 0) {
                uint256 amountToWithdraw = (_amount * weight) / totalWeight;
                IStrategy(strategies[i].strategy).withdraw(amountToWithdraw);
            }
        }
        vaultToken.safeTransfer(msg.sender, _amount);
    }

    function harvest() external onlyOwner {
        for (uint256 i = 0; i < totalWeight; i++) {
            uint256 weight = strategies[i].weight;
            if (weight > 0) {
                IStrategy(strategies[i].strategy).harvest();
                uint256 harvestedAmount = IERC20(vaultToken).balanceOf(address(this));
                strategies[i].lastHarvestTime = block.timestamp;
                emit Harvested(strategies[i].strategy, harvestedAmount);
            }
        }
    }

    function performFee() external onlyOwner {
        uint256 totalBalance = IERC20(vaultToken).balanceOf(address(this));
        if (totalBalance > 0) {
            uint256 fee = (totalBalance * performanceFee) / 10000;
            vaultToken.safeTransfer(msg.sender, fee);
            emit PerformanceFeeWithdrawn(fee);
        }
    }

    function emergencyWithdraw() external onlyOwner {
        for (uint256 i = 0; i < totalWeight; i++) {
            IStrategy(strategies[i].strategy).withdraw(type(uint256).max);
        }
        uint256 balance = IERC20(vaultToken).balanceOf(address(this));
        vaultToken.safeTransfer(msg.sender, balance);
    }

    function getStrategyBalance(address _strategy) external view returns (uint256) {
        return IStrategy(_strategy).balanceOf();
    }
}

