pragma solidity ^0.8.0;

import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import "@uniswap/v2-core/contracts/interfaces/IUniswapV2Pair.sol";
import "@uniswap/v2-periphery/contracts/interfaces/IUniswapV2Router01.sol";

contract AutoCompoundingVault {
    using SafeERC20 for IERC20;

    address public owner;
    IUniswapV2Pair public pair;
    IUniswapV2Router01 public router;

    constructor(address _router, address _pair) {
        owner = msg.sender;
        router = IUniswapV2Router01(_router);
        pair = IUniswapV2Pair(_pair);

        // Approve router to transfer LP tokens
        IERC20(pair).approve(_router, type(uint256).max);
    }

    function compound() external {
        require(msg.sender == owner, "Not authorized");

        uint256 lpBalance = IERC20(pair).balanceOf(address(this));
        if (lpBalance > 0) {
            // Remove liquidity and collect rewards
            address[] memory path = new address[](2);
            path[0] = pair.token0();
            path[1] = pair.token1();

            uint256 token0Amount = IERC20(path[0]).balanceOf(address(this));
            uint256 token1Amount = IERC20(path[1]).balanceOf(address(this));

            router.removeLiquidityETH(
                path[0],
                token0Amount,
                0,
                0,
                address(this),
                block.timestamp
            );

            router.removeLiquidityETH(
                path[1],
                token1Amount,
                0,
                0,
                address(this),
                block.timestamp
            );

            // Add liquidity back to the pool
            router.addLiquidityETH{value: address(this).balance}(
                path[0],
                IERC20(path[0]).balanceOf(address(this)),
                0,
                0,
                address(this),
                block.timestamp
            );
        }
    }

    receive() external payable {}

    function withdrawFunds() external {
        require(msg.sender == owner, "Not authorized");
        uint256 balance = IERC20(pair.token0()).balanceOf(address(this)) +
                          IERC20(pair.token1()).balanceOf(address(this));
        IERC20(pair.token0()).transfer(owner, balance);
    }

    function setRouter(address _router) external {
        require(msg.sender == owner, "Not authorized");
        router = IUniswapV2Router01(_router);
    }

    function setPair(address _pair) external {
        require(msg.sender == owner, "Not authorized");
        pair = IUniswapV2Pair(_pair);

        // Approve router to transfer LP tokens
        IERC20(pair).approve(address(router), type(uint256).max);
    }
}

