pragma solidity ^0.8.0;

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/security/Pausable.sol";

contract YieldAggregator is Ownable, Pausable {
    struct Strategy {
        address strategyAddress;
        uint256 apy;
    }

    Strategy[] public strategies;
    uint256 public currentStrategyIndex;

    event RotationTriggered(uint256 newStrategyIndex);
    event StrategyAdded(address strategyAddress, uint256 apy);
    event StrategyUpdated(address strategyAddress, uint256 newApy);

    modifier onlyKeeper() {
        require(msg.sender == owner(), "Not authorized");
        _;
    }

    function addStrategy(address _strategyAddress, uint256 _apy) external onlyOwner {
        strategies.push(Strategy(_strategyAddress, _apy));
        emit StrategyAdded(_strategyAddress, _apy);
    }

    function updateStrategy(uint256 _index, uint256 _newApy) external onlyKeeper {
        require(_index < strategies.length, "Invalid strategy index");
        strategies[_index].apy = _newApy;
        emit StrategyUpdated(strategies[_index].strategyAddress, _newApy);
    }

    function triggerRotation() external onlyKeeper whenNotPaused {
        uint256 highestApyIndex = 0;

        for (uint256 i = 1; i < strategies.length; i++) {
            if (strategies[i].apy > strategies[highestApyIndex].apy) {
                highestApyIndex = i;
            }
        }

        currentStrategyIndex = highestApyIndex;
        emit RotationTriggered(highestApyIndex);
    }

    function getCurrentStrategy() external view returns (address, uint256) {
        return (strategies[currentStrategyIndex].strategyAddress, strategies[currentStrategyIndex].apy);
    }

    function pause() external onlyOwner whenNotPaused {
        _pause();
    }

    function unpause() external onlyOwner whenPaused {
        _unpause();
    }
}

