pragma solidity ^0.8.0;

contract YieldAggregator {
    struct Pool {
        address asset;
        uint256 balance;
        uint256 yieldRate;
    }

    mapping(address => Pool) public pools;

    event PoolAdded(address indexed asset, uint256 yieldRate);
    event DepositMade(address indexed user, address indexed asset, uint256 amount);
    event WithdrawalMade(address indexed user, address indexed asset, uint256 amount);

    function addPool(address _asset, uint256 _yieldRate) public {
        require(pools[_asset].balance == 0, "Pool already exists");
        pools[_asset] = Pool(_asset, 0, _yieldRate);
        emit PoolAdded(_asset, _yieldRate);
    }

    function deposit(address _asset, uint256 _amount) public {
        Pool storage pool = pools[_asset];
        require(pool.balance > 0, "Pool not found");
        pool.balance += _amount;
        emit DepositMade(msg.sender, _asset, _amount);
    }

    function withdraw(address _asset, uint256 _amount) public {
        Pool storage pool = pools[_asset];
        require(pool.balance >= _amount, "Insufficient balance");
        pool.balance -= _amount;
        emit WithdrawalMade(msg.sender, _asset, _amount);
    }

    function calculateYield(address _asset, uint256 _timeElapsed) public view returns (uint256) {
        Pool storage pool = pools[_asset];
        require(pool.balance > 0, "Pool not found");
        return pool.balance * pool.yieldRate * _timeElapsed / 365 days;
    }
}

